class ItemsView extends VerticalLayout {

    final TextField item;
    final Button addBtn;
    final Button clearBtn;
    final UnorderedList items;
    final Span count;

    ItemsView() {
        item = new TextField("Item");

        addBtn = new Button("Add", event -> addItem());
        addBtn.addThemeVariants(ButtonVariant.PRIMARY);

        clearBtn = new Button("Clear", event -> clearItems());

        var form = new HorizontalLayout(item, addBtn, clearBtn);
        form.setAlignItems(FlexComponent.Alignment.BASELINE);

        items = new UnorderedList();
        count = new Span();
        updateCount();

        add(new ViewTitle("Items"), form, count, items);
    }

    private void addItem() {
        var value = item.getValue();
        if (value.isBlank()) {
            item.setInvalid(true);
            item.setErrorMessage("Item is required");
            return;
        }
        items.add(new ListItem(value));
        item.clear();
        item.setInvalid(false);
        updateCount();
    }

    private void clearItems() {
        items.removeAll();
        updateCount();
    }

    private void updateCount() {
        count.setText("Items: " + items.getComponentCount());
    }
}
